mcp:tool-listener.mcp:parameters-schema:
{
        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "properties": {
          "query": {
            "type": "string",
            "minLength": 1,
            "description": "Natural-language search query"
          },
          "limit": {
            "type": "integer",
            "minimum": 1,
            "maximum": 10,
            "default": 5,
            "description": "Maximum number of hits to return"
          }
        },
        "required": ["query"]
      }

{
        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "minLength": 1,
            "description": "Document id without .md, matching a search_knowledge hit"
          }
        },
        "required": ["id"]
      }
